export function sharedPhase(ms){return Math.floor(((ms%4800)+4800)%4800/50)}
export function applyDerivedWater(host,indices,rgb,phase,meta,contract,proofPin){
 const no=()=>({available:false,written:0}),hex=v=>typeof v==='string'&&/^[0-9a-f]{64}$/i.test(v),nonempty=v=>typeof v==='string'&&v.trim().length>0;if(!meta||!contract||!contract.derivedSource||!hex(meta.sourceSHA)||!hex(contract.derivedSource.sha256)||!hex(meta.proofPin)||!hex(proofPin)||!nonempty(meta.derivedRevision)||!nonempty(contract.derivedRevision)||!(host instanceof Uint8Array||host instanceof Uint8ClampedArray)||!(indices instanceof Uint32Array)||!(rgb instanceof Uint8Array)||!Array.isArray(meta.camera)||meta.camera.length!==4)return no();let[cx,cy,w,h]=meta.camera;if(![cx,cy,w,h].every(Number.isInteger)||cx<0||cy<0||w<1||h<1||cx+w>5120||cy+h>1536||host.length!==w*h*4)return no();
 if(meta.sourceSHA!==contract.derivedSource.sha256||meta.derivedRevision!==contract.derivedRevision||meta.proofPin!==proofPin||meta.regionsVerified!==true||meta.enabled!==true||meta.conflict!==false||!Number.isInteger(phase)||phase<0||phase>=96||indices.length!==145721||rgb.length!==48*145721*3)return no();
 let written=0;for(let i=0;i<indices.length;i++){let id=indices[i],x=id%5120-cx,y=Math.floor(id/5120)-cy;if(x<0||x>=w||y<0||y>=h)continue;let d=(y*w+x)*4,s=((phase%48)*indices.length+i)*3;host[d]=rgb[s];host[d+1]=rgb[s+1];host[d+2]=rgb[s+2];written++;}return{available:true,written};
}
